values
  ('49ca39db-1038-4f72-8be6-df12f64a0ba9', 'dfb3caae-bcf2-43e3-9525-01dd162aca5b', null, 'topic'::public.curated_course_node_type, 'Engineering Drawing Standards (ANSI/ISO)', 'Engineering graphics begins with shared drawing conventions. Standards let designers, manufacturers, reviewers, and field teams interpret drawings consistently.', 0),
  ('d79c9e67-514a-46aa-8e21-ebd30fbbee0b', 'dfb3caae-bcf2-43e3-9525-01dd162aca5b', '49ca39db-1038-4f72-8be6-df12f64a0ba9', 'subtopic'::public.curated_course_node_type, 'Purpose of standards', 'Students learn why engineering drawings are governed by conventions rather than personal preference.', 0),
