  ('fd2cbbb7-3b73-4a6f-a1c7-7339f890b719', 'dfb3caae-bcf2-43e3-9525-01dd162aca5b', null, 'topic'::public.curated_course_node_type, 'Orthographic Projection', 'Orthographic projection is the core skill for representing 3D objects with precise 2D views that can be manufactured, inspected, or modeled.', 1),
