  ('19ba56a4-339d-4854-a1c2-da445bdad57e', 'dfb3caae-bcf2-43e3-9525-01dd162aca5b', null, 'topic'::public.curated_course_node_type, 'Isometric and Pictorial Drawings', 'Pictorial drawings help communicate form quickly. They are less precise than orthographic drawings, but excellent for visualization and design communication.', 2),
